@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1766  cases=55
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-177
  @fn seedItems(h, takes, srcLen)  @ 193-198
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 200-209
  @fn trackList(trackCount)  @ 211-217
  @fn mapBox(tv, take)  @ 220-224
      -- The box the map draws for a take: the travel consumes the window's own shapes.
  @fn mapTracker(harness, inst, trackCount)  @ 229-243
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.
      -- Returns the page's tv, the harness behind it for the cmgr, and the page itself.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 247-255
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 258-267
  @case 'focusState before any render returns both bits false'  [harness]  @ 270-277
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 283-296
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 300-317
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 323-344
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 350-368
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 375-393
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 399-432
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 436-460
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 466-496
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 500-521
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 525-538
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 544-578
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 582-596
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 600-623
  @case 'a track step lands on the placement overlapping the current instance most'  [harness]  @ 627-663
  @case 'with nothing overlapping, a track step lands on the placement nearest in time'  [harness]  @ 667-702
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 709-726
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 730-753
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 757-780
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 784-819
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 823-871
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 875-912
  @case 'deleting the instance drops that placement and lands on the one before it'  [harness]  @ 916-950
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 954-970
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 979-997
  @case 'the map window pages time, a start in the last bar opening the next page'  [harness]  @ 1001-1017
  @case 'with the tracker in no instance the map window pages on the edit cursor'  [harness]  @ 1021-1028
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 1032-1043
  @case 'the map window carries the transport it meets, and only that'  [harness]  @ 1047-1070
  @case 'the map loop candidate snaps to the cell, widens to one, and holds at 0'  [harness]  @ 1074-1093
  @case 'the map drives the transport, and a hand-set loop drops loop to item'  [harness]  @ 1097-1108
  @case 'a click on a map box travels to its instance, across tracks as well as slots'  [harness]  @ 1112-1151
  @case 'a map box that is no stop refuses the travel, as the walk passes it over'  [harness]  @ 1155-1169
  @case 'the pin key holds the map up as the palette default, and drops it when pressed again'  [harness]  @ 1173-1182
  @case 'a gesture raises the map, and it falls at the next command'  [harness]  @ 1186-1227
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 1231-1258
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 1262-1286
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 1293-1314
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 1320-1344
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1351-1370
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1374-1393
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1397-1419
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1425-1443
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1447-1465
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1469-1491
  @case 'Esc clears the loop and drops loop to item with it'  [harness]  @ 1495-1506
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1510-1534
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1540-1595
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1603-1632
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1638-1681
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1687-1701
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1708-1740
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1744-1764

